document.addEventListener("DOMContentLoaded", () => {
if (window.SEO) SEO.initGlobal();
if (window.Analytics) Analytics.init();
if (window.UI) UI.init();
if (window.Catalog) {
if (document.getElementById("catalogGrid")) Catalog.init();
if (document.getElementById("collectionDetail")) Catalog.initDetail();
if (document.getElementById("clubDetail")) Catalog.initClubPage();
if (document.getElementById("jerseyDetail")) Catalog.initJerseyPage();
}
});
